//! Loading sections from `config/*.toml`, `.env` files and the environment.

use std::any::{Any, TypeId};
use std::collections::{BTreeMap, HashMap};
use std::fmt;
use std::io::ErrorKind;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use serde::de::DeserializeOwned;
use toml::{Table, Value};

use crate::environment::Environment;
use crate::error::{ConfigErrors, ConfigIssue};

/// Produces a field's default as a TOML value (generated by `#[config(default = ...)]`).
pub type DefaultFn = fn() -> Result<Value, String>;

/// Reads a field's environment variable (generated from [`EnvValue`](crate::EnvValue)).
pub type EnvCoerce = fn(&str) -> Result<Option<Value>, String>;

/// What `#[derive(Config)]` knows about one field.
#[derive(Debug, Clone, Copy)]
pub struct FieldSpec {
    pub name: &'static str,
    pub env: Option<&'static str>,
    pub secret: bool,
    pub default: Option<DefaultFn>,
    pub coerce: Option<EnvCoerce>,
}

/// A struct read from `config/<FILE>.toml`. Implemented by `#[derive(Config)]`.
pub trait ConfigSection: DeserializeOwned + Send + Sync + 'static {
    /// The file stem under `config/`.
    const FILE: &'static str;

    /// The fields with their environment variables and defaults.
    fn fields() -> &'static [FieldSpec];

    /// Cross-field checks that run at boot (`#[config(validate)]` runs `validator::Validate`).
    fn check(&self) -> Result<(), Vec<String>> {
        Ok(())
    }
}

#[doc(hidden)]
pub fn to_value<T: serde::Serialize + ?Sized>(value: &T) -> Result<Value, String> {
    Value::try_from(value).map_err(|error| error.to_string())
}

#[doc(hidden)]
pub fn validate<T: validator::Validate>(value: &T) -> Result<(), Vec<String>> {
    let Err(errors) = value.validate() else {
        return Ok(());
    };
    let mut messages: Vec<String> = errors
        .field_errors()
        .iter()
        .map(|(field, failures)| {
            let reasons: Vec<String> = failures
                .iter()
                .map(|failure| {
                    failure
                        .message
                        .as_ref()
                        .map_or_else(|| failure.code.to_string(), ToString::to_string)
                })
                .collect();
            format!("{field}: {}", reasons.join(", "))
        })
        .collect();
    if messages.is_empty() {
        messages.push(errors.to_string());
    }
    Err(messages)
}

struct LoadContext {
    root: PathBuf,
    vars: BTreeMap<String, String>,
}

type Loaded = (TypeId, &'static str, Arc<dyn Any + Send + Sync>);
type Loader = Box<dyn Fn(&LoadContext) -> Result<Loaded, Vec<ConfigIssue>> + Send + Sync>;

/// Collects the sections to load, then validates them all at once.
#[derive(Default)]
#[must_use]
pub struct ConfigBuilder {
    root: Option<PathBuf>,
    vars: Option<BTreeMap<String, String>>,
    environment: Option<Environment>,
    loaders: Vec<(TypeId, Loader)>,
    provided: Vec<Loaded>,
}

impl fmt::Debug for ConfigBuilder {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ConfigBuilder")
            .field("root", &self.root)
            .field("sections", &self.loaders.len())
            .finish_non_exhaustive()
    }
}

impl ConfigBuilder {
    /// The directory holding `config/` and the `.env` files. Defaults to the current directory,
    /// which is the package root under `cargo run` and `cargo test` of a single package. In a
    /// workspace, `cargo run -p app` from the workspace root starts there instead: call
    /// `.root(..)` (errors name the directory that was searched).
    pub fn root(mut self, root: impl Into<PathBuf>) -> Self {
        self.root = Some(root.into());
        self
    }

    /// Use exactly these variables instead of the process environment and `.env` files.
    /// Meant for tests, which then never depend on (or disturb) the real environment.
    pub fn vars<K, V>(mut self, vars: impl IntoIterator<Item = (K, V)>) -> Self
    where
        K: Into<String>,
        V: Into<String>,
    {
        self.vars = Some(
            vars.into_iter()
                .map(|(k, v)| (k.into(), v.into()))
                .collect(),
        );
        self
    }

    /// Forces the environment, ignoring `APP_ENV`. `Environment::Testing` also makes `.env.testing`
    /// replace `.env`, like Laravel.
    pub fn environment(mut self, environment: Environment) -> Self {
        self.environment = Some(environment);
        self
    }

    /// Loads section `T` from `config/<T::FILE>.toml`, the environment and its defaults.
    pub fn section<T: ConfigSection>(mut self) -> Self {
        self.loaders.push((
            TypeId::of::<T>(),
            Box::new(|ctx| {
                let section = load_section::<T>(ctx)?;
                Ok((TypeId::of::<T>(), T::FILE, Arc::new(section)))
            }),
        ));
        self
    }

    /// Supplies a ready-made section without loading anything (handy for tests). It replaces a
    /// `section::<T>()` for the same type, whose files and environment are then never read.
    pub fn provide<T: ConfigSection>(mut self, section: T) -> Self {
        self.provided
            .push((TypeId::of::<T>(), T::FILE, Arc::new(section)));
        self
    }

    /// Loads everything, reporting every problem at once.
    pub fn load(self) -> Result<Configuration, ConfigErrors> {
        let root = self
            .root
            .or_else(|| std::env::current_dir().ok())
            .unwrap_or_else(|| PathBuf::from("."));
        let mut issues = Vec::new();

        let (vars, environment) = match self.vars {
            Some(vars) => {
                let environment = self
                    .environment
                    .unwrap_or_else(|| environment_from(vars.get("APP_ENV").map(String::as_str)));
                (vars, environment)
            }
            None => resolve_vars(&root, self.environment, &mut issues),
        };

        let ctx = LoadContext { root, vars };
        let mut sections: HashMap<TypeId, (&'static str, Arc<dyn Any + Send + Sync>)> =
            HashMap::new();
        let provided_ids: Vec<TypeId> = self.provided.iter().map(|(id, _, _)| *id).collect();
        for (id, loader) in &self.loaders {
            if provided_ids.contains(id) {
                continue;
            }
            match loader(&ctx) {
                Ok((id, name, section)) => {
                    sections.insert(id, (name, section));
                }
                Err(found) => issues.extend(found),
            }
        }
        for (id, name, section) in self.provided {
            sections.insert(id, (name, section));
        }
        if !issues.is_empty() {
            return Err(ConfigErrors { issues });
        }
        Ok(Configuration {
            inner: Arc::new(Inner {
                environment,
                vars: ctx.vars,
                sections,
            }),
        })
    }
}

fn environment_from(name: Option<&str>) -> Environment {
    name.map(|name| name.parse().unwrap_or_default())
        .unwrap_or_default()
}

/// The variables to use: the process environment over the `.env` file for this environment.
fn resolve_vars(
    root: &Path,
    forced: Option<Environment>,
    issues: &mut Vec<ConfigIssue>,
) -> (BTreeMap<String, String>, Environment) {
    let process: BTreeMap<String, String> = std::env::vars().collect();
    let env_issue = |source: String, message: String| ConfigIssue {
        section: "env".into(),
        field: None,
        source,
        message,
    };

    // The base `.env` can name the environment when the process doesn't.
    let mut base_issues = Vec::new();
    let base = read_dotenv(&root.join(".env"), &mut base_issues, &env_issue);
    let name = forced
        .map(|environment| environment.to_string())
        .or_else(|| process.get("APP_ENV").cloned())
        .or_else(|| base.get("APP_ENV").cloned());
    let environment = environment_from(name.as_deref());

    // Only plain names select an environment file, so `APP_ENV` can't point at other paths.
    let specific = Some(environment.to_string())
        .filter(|name| is_plain_name(name))
        .map(|name| root.join(format!(".env.{name}")))
        .filter(|path| path.is_file());
    let file_vars = if let Some(specific) = specific {
        // `.env.<env>` replaces `.env`, so a broken `.env` is not this run's problem.
        read_dotenv(&specific, issues, &env_issue)
    } else {
        issues.extend(base_issues);
        base
    };

    let mut vars = file_vars;
    vars.extend(process);
    if let Some(name) = name {
        vars.insert("APP_ENV".into(), name);
    }
    (vars, environment)
}

fn is_plain_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
}

fn read_dotenv(
    path: &Path,
    issues: &mut Vec<ConfigIssue>,
    issue: &dyn Fn(String, String) -> ConfigIssue,
) -> BTreeMap<String, String> {
    let mut vars = BTreeMap::new();
    let source = path.file_name().map_or_else(
        || path.display().to_string(),
        |name| name.to_string_lossy().into_owned(),
    );
    let entries = match dotenvy::from_path_iter(path) {
        Ok(entries) => entries,
        Err(error) if error.not_found() => return vars,
        Err(error) => {
            issues.push(issue(source, error.to_string()));
            return vars;
        }
    };
    for entry in entries {
        match entry {
            Ok((key, value)) => {
                vars.insert(key, value);
            }
            Err(error) => issues.push(issue(source.clone(), error.to_string())),
        }
    }
    vars
}

fn load_section<T: ConfigSection>(ctx: &LoadContext) -> Result<T, Vec<ConfigIssue>> {
    let file = format!("config/{}.toml", T::FILE);
    let mut issues = Vec::new();
    let issue = |field: Option<&str>, source: &str, message: String| ConfigIssue {
        section: T::FILE.to_owned(),
        field: field.map(str::to_owned),
        source: source.to_owned(),
        message,
    };

    let mut table = Table::new();
    let mut file_found = false;
    match std::fs::read_to_string(ctx.root.join(&file)) {
        Ok(text) => {
            file_found = true;
            match text.parse::<Table>() {
                Ok(parsed) => table = parsed,
                // Not `error.to_string()`: that quotes the offending source line, which may be
                // a secret.
                Err(error) => issues.push(issue(None, &file, parse_message(&text, &error))),
            }
        }
        Err(error) if error.kind() == ErrorKind::NotFound => {}
        Err(error) => issues.push(issue(None, &file, error.to_string())),
    }

    for spec in T::fields() {
        if !table.contains_key(spec.name)
            && let Some(default) = spec.default
        {
            match default() {
                Ok(value) => {
                    table.insert(spec.name.to_owned(), value);
                }
                Err(message) => issues.push(issue(
                    Some(spec.name),
                    "default",
                    format!("the default can't be represented in TOML: {message}"),
                )),
            }
        }
    }

    for spec in T::fields() {
        let (Some(var), Some(coerce)) = (spec.env, spec.coerce) else {
            continue;
        };
        let Some(raw) = ctx.vars.get(var) else {
            continue;
        };
        let source = format!("${var}");
        match coerce(raw) {
            Ok(Some(value)) => {
                table.insert(spec.name.to_owned(), value);
            }
            Ok(None) => {
                table.remove(spec.name);
            }
            Err(message) => {
                let message = if spec.secret {
                    message
                } else {
                    format!("{message}, got `{raw}`")
                };
                issues.push(issue(Some(spec.name), &source, message));
            }
        }
    }
    if !issues.is_empty() {
        return Err(issues);
    }

    // Secrets from any source (file, default or environment) are masked in later messages.
    let secrets: Vec<String> = T::fields()
        .iter()
        .filter(|spec| spec.secret)
        .filter_map(|spec| table.get(spec.name))
        .map(|value| match value {
            Value::String(text) => text.clone(),
            other => other.to_string(),
        })
        .filter(|text| !text.is_empty())
        .collect();
    let origin = if file_found {
        file.clone()
    } else {
        format!(
            "environment and defaults; no {file} under {}",
            ctx.root.display()
        )
    };
    let section: T = Value::Table(table)
        .try_into()
        .map_err(|error: toml::de::Error| {
            let mut message = error.message().to_owned();
            for secret in &secrets {
                message = message.replace(secret.as_str(), "[REDACTED]");
            }
            vec![issue(None, &origin, message)]
        })?;
    section.check().map_err(|messages| {
        messages
            .into_iter()
            .map(|message| issue(None, "validation", message))
            .collect::<Vec<_>>()
    })?;
    Ok(section)
}

/// `line 3, column 5: <message>` for a TOML syntax error, without the quoted source.
fn parse_message(text: &str, error: &toml::de::Error) -> String {
    let message = error.message();
    let Some(span) = error.span() else {
        return message.to_owned();
    };
    let before = &text[..span.start.min(text.len())];
    let line = before.matches('\n').count() + 1;
    let column = before
        .rsplit('\n')
        .next()
        .map_or(0, |last| last.chars().count())
        + 1;
    format!("line {line}, column {column}: {message}")
}

struct Inner {
    environment: Environment,
    vars: BTreeMap<String, String>,
    sections: HashMap<TypeId, (&'static str, Arc<dyn Any + Send + Sync>)>,
}

/// The loaded configuration: every section plus the environment. Cheap to clone; put it in your
/// service container and take [`Config<T>`](struct@crate::Config) in handlers.
#[derive(Clone, oxide_http::Service)]
pub struct Configuration {
    inner: Arc<Inner>,
}

impl fmt::Debug for Configuration {
    /// Lists section names only, never values.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut sections: Vec<&str> = self
            .inner
            .sections
            .values()
            .map(|(name, _)| *name)
            .collect();
        sections.sort_unstable();
        f.debug_struct("Configuration")
            .field("environment", &self.inner.environment)
            .field("sections", &sections)
            .finish()
    }
}

impl Configuration {
    pub fn builder() -> ConfigBuilder {
        ConfigBuilder::default()
    }

    pub fn environment(&self) -> &Environment {
        &self.inner.environment
    }

    /// A raw environment variable as the application sees it (process environment over `.env`),
    /// like Laravel's `env()`. Prefer typed sections; use this for ad-hoc keys.
    pub fn env(&self, key: &str) -> Option<&str> {
        self.inner.vars.get(key).map(String::as_str)
    }

    /// Section `T`, or `None` if it wasn't registered with [`ConfigBuilder::section`].
    pub fn get<T: ConfigSection>(&self) -> Option<Arc<T>> {
        let (_, section) = self.inner.sections.get(&TypeId::of::<T>())?;
        Arc::clone(section).downcast::<T>().ok()
    }

    /// Like [`get`](Self::get), but a missing section is an error you can `?` out of `main`.
    pub fn require<T: ConfigSection>(&self) -> Result<Arc<T>, ConfigErrors> {
        self.get::<T>().ok_or_else(|| ConfigErrors {
            issues: vec![ConfigIssue {
                section: T::FILE.to_owned(),
                field: None,
                source: "ConfigBuilder".to_owned(),
                message: "the section was not registered; add `.section::<..>()` before `load()`"
                    .to_owned(),
            }],
        })
    }
}
